insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 1, 1, '{"place":"The forest road","narrated":true,"tone":"wry","cupNight":false,"opener":"One list, one inn''s name. Nothing was taken.","forkA":"The list is a warning.","forkB":"The list is an invitation.","callback":null,"nudge":"{friend:Intellect}, what is odd about a stranger who leaves something behind?","riddle":null,"leads":[{"id":"1-1-1","place":"the list, by the last light","actions":[{"attr":"Intellect","verb":"read it again, line by line"},{"attr":"Craft","verb":"hold it to the light and look at the ink"}],"clueTitle":"The even hand","clueText":"Not one name is crossed out or written over. Every line sits level, and the inn''s line is in the same hand as the names.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"1-1-2","place":"the trees where he went","actions":[{"attr":"Agility","verb":"go after him into the trees"},{"attr":"Aim","verb":"pick out his trail in the dusk"}],"clueTitle":"Two sets of boots","clueText":"Twenty paces in, his prints meet another man''s. The two go on together, at a walk.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"1-1-3","place":"the bottom of the cargo box","actions":[{"attr":"Craft","verb":"take the box apart, board by board"},{"attr":"Intellect","verb":"go through it a third time"}],"clueTitle":"The oilcloth","clueText":"Under your things lies a square of oilcloth you never packed, folded small. Whatever he put in the box, he wrapped it first against the wet.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"One stayed close.\"* Close to what?","weekQuestion":"Why are our names on that list?","pull":"A man broke into your box to leave you a list with your name on it.\n\n**One day north: the Hollow Wake Inn. Somebody wants you there.**"}'::jsonb),
('dark-moon', 1, 1, 2, '{"place":"The Hollow Wake Inn","narrated":false,"tone":"wry","cupNight":true,"opener":"You''ve paid for your rooms and you haven''t burned anything down. That''s more than most guests manage.","forkA":"Meira left in a hurry.","forkB":"Meira left on purpose.","callback":"She hasn''t sat in that seat for three weeks. Your pages all reached you on the road within the same few days.","nudge":"{friend:Craft}, how would you test whether the page is hers?","riddle":{"q":"What has a neck but no head?","a":"a bottle","quip":"The inn is full of them. None of them talk.","accept":["a bottle","bottle"],"maxTries":3},"leads":[{"id":"1-2-1","place":"the bottom of her satchel","actions":[{"attr":"Intellect","verb":"empty it out onto the table"},{"attr":"Craft","verb":"feel along the lining"}],"clueTitle":"Bread and a candle","clueText":"In the bottom of the satchel: a heel of bread in a cloth, hard as wood, and a new candle that was never lit.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"1-2-2","place":"the notebook, page by page","actions":[{"attr":"Intellect","verb":"go through it, leaf by leaf"},{"attr":"Craft","verb":"look at how each page is kept"}],"clueTitle":"Every slip pinned","clueText":"Every loose slip in the notebook is pinned to the page it belongs with. Not one is out of place.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"1-2-3","place":"the seat that was hers","actions":[{"attr":"Aim","verb":"sit where she sat and look out"},{"attr":"Agility","verb":"go from her seat to the nearest door"}],"clueTitle":"The worn end","clueText":"Her seat is the end of a bench. It is worn pale on one side only: the side nearer the door.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"They wept for him before they feared him.\"* What changed between the two?","weekQuestion":"Why are our names on that list?","pull":"**First light. Two hours north. A child was held at that rock, and whatever it is has not finished.**"}'::jsonb),
('dark-moon', 1, 1, 3, '{"place":"The Widow''s Tooth","narrated":false,"tone":"wry","cupNight":false,"opener":"You''ve not eaten. Sit.","forkA":"The man in the bracken was guarding the rock.","forkB":"He was waiting for us.","callback":"The man on the forest road was carrying her rubbing. The man in the bracken was watching her rock.","nudge":"{friend:Aim}, from his hollow in the bracken, what was he watching?","riddle":{"q":"The more you take, the more you leave behind. What am I?","a":"footsteps","quip":"There''s bracken full of them out there.","accept":["footsteps"],"maxTries":3},"leads":[{"id":"1-3-1","place":"the bracken where he waited","actions":[{"attr":"Agility","verb":"crawl into his hollow in the bracken"},{"attr":"Intellect","verb":"read the ground he lay on"}],"clueTitle":"The second ring","clueText":"In the flattened bracken a flask has left a ring in the dew, and a second ring beside it where he set it down again.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"1-3-2","place":"the far side of the rock","actions":[{"attr":"Might","verb":"climb round the split to the far side"},{"attr":"Intellect","verb":"pace out the ground round its foot"}],"clueTitle":"The worn path","clueText":"Round the foot of the rock the turf is worn to bare earth in a narrow path, all the way round. Someone walks round this stone, and often.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"1-3-3","place":"the gap he ran through","actions":[{"attr":"Agility","verb":"run his line to the trees"},{"attr":"Aim","verb":"search the ground he crossed"}],"clueTitle":"The notched stick","clueText":"In the gap where he ran, a stick lies dropped, notched down one side. The newest notches are still pale and wet.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Some locks already know their key.\"* Whose key?","weekQuestion":"Why are our names on that list?","pull":"Garrick has not gone back to his inn. He is standing in the road with his pack on, looking at the smoke.\n\n**The ruts go that way. So did the man. He will be there before you, and every door will be shut when you come.**"}'::jsonb),
('dark-moon', 1, 1, 4, '{"place":"Fenmark","narrated":false,"tone":"quiet","cupNight":false,"opener":"A village that won''t talk is still talking. Mostly with its shutters.","forkA":"The village is protecting the girl.","forkB":"The village is protecting itself.","callback":"The boy says they moved like they''d done it before. The little horse at the rock had sat out a winter or two.","nudge":"{friend:Charm}, when Fenmark shut its doors on us, who was it protecting?","riddle":{"q":"What breaks the moment you say its name?","a":"silence","quip":"Fenmark''s had plenty of practice.","accept":["silence"],"maxTries":3},"leads":[{"id":"1-4-1","place":"the gate at the end of the lane","actions":[{"attr":"Craft","verb":"look at how the gate was left"},{"attr":"Might","verb":"lift the bar and feel its weight"}],"clueTitle":"The leaned bar","clueText":"The gate at the end of the lane is swinging, but its bar has been lifted and leaned neatly against the post, not thrown down.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"1-4-2","place":"the one open shutter","actions":[{"attr":"Charm","verb":"stop at the open shutter and wait"},{"attr":"Aim","verb":"look in from across the lane"}],"clueTitle":"The covered cup","clueText":"On the sill of the open shutter stands a cup of milk with a cloth over it. Under the window, a child''s stool is set square to the wall.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"1-4-3","place":"where the elder''s men stood","actions":[{"attr":"Intellect","verb":"look over the ground where they stood"},{"attr":"Craft","verb":"pick through what they left in the mud"}],"clueTitle":"Fresh bark","clueText":"Where the men stood with the elder, curls of fresh bark lie in the mud. Somebody in Fenmark cut a cudgel today.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Marked before the first cry''s through.\"* Marked by whom, and for what?","weekQuestion":"Why are our names on that list?","pull":"**East. Two hours. He has half a day on you, and he is heading for the only other person alive who has seen that knife.**"}'::jsonb),
('dark-moon', 1, 1, 5, '{"place":"The old charcoal camp","narrated":false,"tone":"wry","cupNight":false,"opener":"Two winters between two children. Some people count in winters. It''s a way of keeping still.","forkA":"It''s the same man, twice.","forkB":"It''s a way of working, not one man.","callback":"The road, the rock, and tonight her shutters. Not one of those men has said a word.","nudge":"{friend:Intellect}, two children, two winters apart. One man''s habit, or someone''s way of working?","riddle":{"q":"I grow, but I''m not alive. I need air, but I have no lungs. Water kills me. What am I?","a":"fire","quip":"Which is why I tend this one myself.","accept":["fire"],"maxTries":3},"leads":[{"id":"1-5-1","place":"the woman at the edge of the firelight","actions":[{"attr":"Charm","verb":"sit with her and let her talk"},{"attr":"Intellect","verb":"ask her what she saw two winters back"}],"clueTitle":"The knife, not the face","clueText":"She says she never saw his face, only the knife, and it is the knife she knows him by.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"1-5-2","place":"the shutter he was trying","actions":[{"attr":"Craft","verb":"run a thumb along the marks in the wood"},{"attr":"Intellect","verb":"set the old marks beside the new"}],"clueTitle":"Older marks","clueText":"Under his fresh marks on the shutter are older ones, grey with weather, worked in at the same place, where the bar sits.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"1-5-3","place":"the clean path in","actions":[{"attr":"Aim","verb":"read the path by the firelight"},{"attr":"Intellect","verb":"count the prints worn into it"}],"clueTitle":"One pair of boots","clueText":"The path in is worn by one pair of small boots, hers, over and over. Under them you find no other prints but tonight''s.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"The power that gives is also the power that takes.\"* What has been given this week, and what has been taken?","weekQuestion":"Why are our names on that list?","pull":"At first light she walks you to the edge of the camp, and stands on the old charcoal road, and points.\n\n**North. The same man, the same country, the same season. If it comes round like a calendar, the time is now.**"}'::jsonb),
('dark-moon', 1, 1, 6, '{"place":"The Low Ford","narrated":false,"tone":"wry","cupNight":true,"opener":"Six pieces, one map. Eat something before you stare at it.","forkA":"They carried her across the water.","forkB":"They wanted us to think so.","callback":"Meira had this shape on paper before any of you found a piece. Tonight the pieces drew it.","nudge":"{friend:Intellect}, what do you notice about how the pieces settled?","riddle":{"q":"I have a bed but never sleep, a mouth but never speak. What am I?","a":"a river","quip":"The one in front of us says nothing, and I believe it.","accept":["a river","river"],"maxTries":3},"leads":[{"id":"1-6-1","place":"the far bank, along the water","actions":[{"attr":"Aim","verb":"scan the far bank from the ford-stone"},{"attr":"Might","verb":"wade the safe line across"}],"clueTitle":"Threads on a thorn","clueText":"On a thorn at the water''s edge of the far bank, a little way along from the ruts, a few woollen threads hang at the height of a child.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"1-6-2","place":"the ruts up the far bank","actions":[{"attr":"Craft","verb":"read the hoofprints beside the ruts"},{"attr":"Might","verb":"cross and walk the ruts up the bank"}],"clueTitle":"Up at a run","clueText":"Beside the ruts, the horse''s prints up the far bank are short, deep and dug in at the toe. It went up at a run.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"1-6-3","place":"the heel-marks at the water","actions":[{"attr":"Agility","verb":"get down to them before the river does"},{"attr":"Intellect","verb":"work out whose feet went where"}],"clueTitle":"A second man","clueText":"Beside the heel-marks, a second man''s prints come down from the cart to the water and go straight back up to it.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"The key that locks.\"* What is locked, and who holds the key?","weekQuestion":"Why are our names on that list?","pull":"**Cross at first light. You will be there by morning. Whatever is at the place the map marks, the season for it is now.**"}'::jsonb)
